require_once __DIR__.'/includes/letters.php';Auth::requireLogin();$type=(string)($_GET['type']??'');$id=(int)($_GET['id']??0);$field=(string)($_GET['field']??'');$letterId=(int)($_GET['letter_id']??0);$row=null;$path='';$download=false;$name='file';
if($type==='attachment'){$row=Database::fetch('SELECT a.*,l.created_by,l.approved_by,l.confidentiality FROM organizational_letter_attachments a JOIN organizational_letters l ON l.id=a.letter_id WHERE a.id=?',[$id]);if($row&&!LetterModule::canViewLetter($row))$row=null;if($row){$path=$row['file_path'];$name=$row['original_name'];$download=true;}}
